inline constexpr char kWebPage[] = R"HTML(
<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no">
  <meta name="theme-color" content="#eef4ff" id="themeColor">
  <title>Kylio Robot Car</title>
  <style>
    :root{--bg:#eef4ff;--card:#fffffff0;--soft:#f5f8ff;--text:#172033;--muted:#68758d;--line:#dce5f2;--blue:#356df3;--blue2:#2458d5;--green:#16a56a;--red:#ef4e5b;--purple:#7250d7;--shadow:0 18px 50px #25438221}
    body.dark{--bg:#0c1220;--card:#141d30f2;--soft:#101a2d;--text:#edf3ff;--muted:#9eabc1;--line:#273550;--blue:#5d88ff;--blue2:#4773ea;--green:#28bd7d;--red:#ff6370;--shadow:0 20px 55px #0005}
    *{box-sizing:border-box;-webkit-tap-highlight-color:transparent}body{margin:0;min-height:100vh;background:radial-gradient(circle at 15% 5%,#356df324,transparent 34%),var(--bg);color:var(--text);font-family:Arial,sans-serif;transition:.2s}button{font:inherit}.app{width:min(100%,980px);margin:auto;padding:22px 18px 105px}.top{display:flex;justify-content:space-between;align-items:center;margin-bottom:18px}.brand{display:flex;align-items:center;gap:12px}.logo{display:grid;place-items:center;width:48px;height:48px;border-radius:15px;background:linear-gradient(135deg,var(--blue),#7d55ef);font-size:25px}.top h1{font-size:26px;margin:0}.sub,.hint{color:var(--muted);font-size:13px;margin:4px 0 0}.theme{width:45px;height:45px;border:1px solid var(--line);border-radius:14px;background:var(--card);cursor:pointer}.telemetry{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:18px}.chip{padding:8px 11px;border:1px solid var(--line);border-radius:999px;background:var(--card);font-size:12px}.layout{display:grid;grid-template-columns:210px 1fr;gap:20px}.menu{display:flex;flex-direction:column;gap:7px;align-self:start;padding:10px;border:1px solid var(--line);border-radius:22px;background:var(--card);box-shadow:var(--shadow)}.menu button{padding:13px;border:0;border-radius:14px;background:transparent;color:var(--muted);font-weight:700;text-align:left;cursor:pointer}.menu button.active{background:var(--blue);color:white}.panel{display:none;min-height:430px;padding:32px;border:1px solid var(--line);border-radius:26px;background:var(--card);box-shadow:var(--shadow)}.panel.active{display:block}.panel-head{display:flex;justify-content:space-between;gap:12px;margin-bottom:25px}.panel h2{margin:0 0 7px}.badge{height:27px;padding:6px 10px;border-radius:99px;background:#ef4e5b1c;color:var(--red);font-size:11px;font-weight:800}.badge.on{background:#16a56a1c;color:var(--green)}.drive-pad{display:grid;grid-template-columns:repeat(3,78px);grid-template-rows:repeat(3,68px);justify-content:center;gap:10px}.drive,.rotate{border:0;border-radius:18px;background:linear-gradient(145deg,var(--blue),var(--blue2));color:white;font-size:27px;font-weight:bold;cursor:pointer;touch-action:none;user-select:none;box-shadow:0 8px 18px #356df33b}.drive:active,.rotate:active{transform:scale(.95)}.stop{background:linear-gradient(145deg,var(--red),#d63846)}.rotate-row{display:grid;grid-template-columns:repeat(2,120px);justify-content:center;gap:12px;margin-top:14px}.rotate{min-height:52px;background:linear-gradient(145deg,var(--purple),#5437b5);font-size:20px}.mode-card{display:grid;place-items:center;min-height:255px;padding:25px;border:1px solid var(--line);border-radius:22px;background:var(--soft);text-align:center}.mode-icon{font-size:42px;margin-bottom:13px}.actions{display:grid;grid-template-columns:1fr 1fr;gap:12px;width:min(100%,410px);margin-top:22px}.actions button{min-height:54px;border:0;border-radius:16px;color:white;font-weight:800;cursor:pointer}.on-btn{background:var(--green)}.off-btn{background:var(--red)}.open-btn{background:var(--blue)}button:disabled{filter:grayscale(1);opacity:.4;cursor:not-allowed}.error{display:none;margin-bottom:14px;padding:11px 14px;border-radius:12px;background:#ef4e5b1c;color:var(--red);font-size:13px}.error.show{display:block}
    @media(max-width:700px){.app{padding:16px 13px 105px}.layout{display:block}.panel{padding:24px 17px;min-height:440px}.menu{position:fixed;z-index:10;left:10px;right:10px;bottom:10px;display:grid;grid-template-columns:repeat(5,1fr);padding:7px}.menu button{text-align:center;padding:11px 3px;font-size:11px}.drive-pad{grid-template-columns:repeat(3,72px)}}
  </style>
</head>
<body>
<main class="app">
  <header class="top"><div class="brand"><div class="logo">🚗</div><div><h1>Kylio Robot Car</h1><p class="sub">ESP-IDF Control Dashboard</p></div></div><button class="theme" id="themeBtn" onclick="toggleTheme()">🌙</button></header>
  <div class="telemetry"><span class="chip" id="ipChip">IP: --</span><span class="chip" id="distanceChip">Distance: --</span><span class="chip" id="motionChip">Motion: stopped</span><span class="chip" id="safetyChip">Front brake: ready</span></div>
  <div class="error" id="errorBox"></div>
  <div class="layout">
    <nav class="menu"><button class="active" onclick="showPanel('manual',this)">🎮 Manual</button><button onclick="showPanel('obstacle',this)">🛡️ Obstacle</button><button onclick="showPanel('follow',this)">👣 Follow</button><button onclick="showPanel('room',this)">🏠 Room</button><button onclick="showPanel('telegram',this)">✈️ Telegram</button></nav>
    <section>
      <article class="panel active" id="manual"><div class="panel-head"><div><h2>Manual Control</h2><p class="sub">Press and hold to move. Releasing or losing connection stops the car.</p></div><span class="badge on">READY</span></div>
        <div class="drive-pad"><button class="drive robot-control" data-dir="fl">↖</button><button class="drive robot-control" data-dir="f">▲</button><button class="drive robot-control" data-dir="fr">↗</button><button class="drive robot-control" data-dir="l">◀</button><button class="drive stop" onclick="emergencyStop()">■</button><button class="drive robot-control" data-dir="r">▶</button><button class="drive robot-control" data-dir="bl">↙</button><button class="drive robot-control" data-dir="b">▼</button><button class="drive robot-control" data-dir="br">↘</button></div>
        <div class="rotate-row"><button class="rotate robot-control" data-dir="rl">↺ Left</button><button class="rotate robot-control" data-dir="rr">Right ↻</button></div>
      </article>
      <article class="panel" id="obstacle"><div class="panel-head"><div><h2>Obstacle Avoid</h2><p class="sub">Automatically detects and avoids obstacles.</p></div><span class="badge" id="obstacleStatus">OFF</span></div><div class="mode-card"><div class="mode-icon">🛡️</div><strong>Obstacle Avoid Mode</strong><div class="actions"><button class="on-btn mode-control" onclick="setMode('mode','auto',1)">TURN ON</button><button class="off-btn mode-control" onclick="setMode('mode','auto',0)">TURN OFF</button></div></div></article>
      <article class="panel" id="follow"><div class="panel-head"><div><h2>Follow Mode</h2><p class="sub">Maintains the configured distance from a target.</p></div><span class="badge" id="followStatus">OFF</span></div><div class="mode-card"><div class="mode-icon">👣</div><strong>Target Following</strong><div class="actions"><button class="on-btn mode-control" onclick="setMode('follow','f',1)">FOLLOW ON</button><button class="off-btn mode-control" onclick="setMode('follow','f',0)">FOLLOW OFF</button></div></div></article>
      <article class="panel" id="room"><div class="panel-head"><div><h2>Room Monitor</h2><p class="sub">Calibrates a baseline and reports significant changes.</p></div><span class="badge" id="roomStatus">OFF</span></div><div class="mode-card"><div class="mode-icon">🏠</div><strong>Room Monitoring</strong><div class="actions"><button class="on-btn mode-control" onclick="setMode('room','monitor',1)">MONITOR ON</button><button class="off-btn mode-control" onclick="setMode('room','monitor',0)">MONITOR OFF</button></div></div></article>
      <article class="panel" id="telegram"><div class="panel-head"><div><h2>Telegram</h2><p class="sub">Enable command polling. Robot motion stops when control changes.</p></div><span class="badge" id="telegramStatus">OFF</span></div><div class="mode-card"><div class="mode-icon">✈️</div><strong>Telegram Control</strong><div class="actions"><button class="on-btn" id="telegramToggle" onclick="toggleTelegram()">TELEGRAM ON</button><button class="open-btn" onclick="location.href='https://t.me/'">OPEN TELEGRAM</button></div><p class="hint" id="telegramHint">Web motion controls are locked while Telegram polling is enabled.</p></div></article>
    </section>
  </div>
</main>
<script>
const themeBtn=document.getElementById('themeBtn'),themeColor=document.getElementById('themeColor'),errorBox=document.getElementById('errorBox'),ipChip=document.getElementById('ipChip'),distanceChip=document.getElementById('distanceChip'),motionChip=document.getElementById('motionChip'),safetyChip=document.getElementById('safetyChip'),telegramToggle=document.getElementById('telegramToggle'),telegramHint=document.getElementById('telegramHint');
let state={mode:'manual',telegramEnabled:false,telegramConfigured:false};let holdTimer=null;let heldDir=null;let heartbeatInFlight=false;let commandSequence=Date.now();
function showPanel(id,button){document.querySelectorAll('.panel').forEach(x=>x.classList.remove('active'));document.querySelectorAll('.menu button').forEach(x=>x.classList.remove('active'));document.getElementById(id).classList.add('active');button.classList.add('active')}
function toggleTheme(){const dark=document.body.classList.toggle('dark');themeBtn.textContent=dark?'☀️':'🌙';themeColor.content=dark?'#0c1220':'#eef4ff';localStorage.setItem('kylio-theme',dark?'dark':'light')}
function showError(message=''){errorBox.textContent=message;errorBox.classList.toggle('show',!!message)}
async function request(url,keepalive=false){try{const response=await fetch(url,{cache:'no-store',keepalive});if(!response.ok)throw new Error((await response.text())||`HTTP ${response.status}`);showError();return response}catch(error){showError(error.message);throw error}}
function command(dir,on,keepalive=!on){const sequence=++commandSequence;return request(`/cmd?dir=${encodeURIComponent(dir)}&state=${on?1:0}&seq=${sequence}`,keepalive)}
function sendHeartbeat(){if(!heldDir||heartbeatInFlight)return;const direction=heldDir;heartbeatInFlight=true;command(direction,true).catch(()=>{}).finally(()=>{heartbeatInFlight=false})}
function beginHold(event){if(state.telegramEnabled)return;event.preventDefault();endHold();heldDir=event.currentTarget.dataset.dir;if(event.currentTarget.setPointerCapture)event.currentTarget.setPointerCapture(event.pointerId);sendHeartbeat();holdTimer=setInterval(sendHeartbeat,100)}
function endHold(){if(holdTimer){clearInterval(holdTimer);holdTimer=null}if(heldDir){const direction=heldDir;heldDir=null;command(direction,false).catch(()=>{})}}
function emergencyStop(){endHold();command('s',true,true).then(refresh).catch(()=>{})}
async function setMode(path,key,value){endHold();await request(`/${path}?${key}=${value}`);await refresh()}
async function toggleTelegram(){const value=state.telegramEnabled?0:1;endHold();await request(`/telegram?enabled=${value}`);await refresh()}
function badge(id,on,label){const item=document.getElementById(id);item.textContent=label||(on?'ON':'OFF');item.classList.toggle('on',on)}
async function refresh(){try{const response=await request('/api/state');state=await response.json();ipChip.textContent=`IP: ${state.ip}`;distanceChip.textContent=`Distance: ${state.distanceCm===null?'ERROR':state.distanceCm.toFixed(1)+' cm'}`;motionChip.textContent=`Motion: ${state.motion}`;safetyChip.textContent=state.manualFrontBrakeActive?'Front brake: ACTIVE':'Front brake: ready';badge('obstacleStatus',state.mode==='obstacle');badge('followStatus',state.mode==='follow');badge('roomStatus',state.mode==='room',state.roomCalibrating?'CALIBRATING':state.mode==='room'?'ON':'OFF');badge('telegramStatus',state.telegramEnabled);document.querySelectorAll('.robot-control,.mode-control').forEach(x=>x.disabled=state.telegramEnabled);telegramToggle.textContent=state.telegramEnabled?'TELEGRAM OFF':'TELEGRAM ON';telegramToggle.className=state.telegramEnabled?'off-btn':'on-btn';telegramToggle.disabled=!state.telegramConfigured&&!state.telegramEnabled;telegramHint.textContent=state.telegramConfigured?'Web motion controls are locked while Telegram polling is enabled.':'Telegram credentials are not configured.'}catch(_){}}
document.querySelectorAll('[data-dir]').forEach(button=>{button.addEventListener('pointerdown',beginHold);button.addEventListener('pointerup',endHold);button.addEventListener('pointercancel',endHold);button.addEventListener('lostpointercapture',endHold)});window.addEventListener('blur',endHold);document.addEventListener('visibilitychange',()=>{if(document.hidden)endHold()});if(localStorage.getItem('kylio-theme')==='dark')toggleTheme();refresh();setInterval(refresh,1000);
</script>
</body>
</html>
)HTML";
